!> Behavior-lock tests for model Hessian variants
!>
!> Reference Hessians are embedded below as parameter arrays, one packed
!> Hessian per test, compared element-wise. Deliberate model changes must
!> update the corresponding ref_* array; regenerate values by temporarily
!> printing the computed packed Hessian in test_mh
module test_model_hessian
   use testdrive, only : new_unittest, unittest_type, error_type, check
   use xtb_mctc_accuracy, only : wp
   use xtb_chargemodel, only : new_charge_model_2019
   use xtb_gfnff_calculator, only : TGFFCalculator, newGFFCalculator
   use xtb_modelhessian_gff, only : TGFFModelHessian, newGFFModelHessian
   use xtb_type_molecule, only : TMolecule
   use xtb_modelhessian_eeq, only : add_eeq_hessian
   use xtb_modelhessian_type, only : TModelHessian
   use xtb_modelhessian_lindh, only : TLindhModelHessian, &
      & newLindhModelHessian, newLindhD2ModelHessian
   use xtb_modelhessian_swart, only : newSwartModelHessian
   use xtb_type_param, only : chrg_parameter
   use xtb_type_setvar, only : modhess_setvar
   use xtb_test_molstock, only : getMolecule
   use xtb_type_environment, only : TEnvironment, init
   implicit none(type, external)
   private
   public :: collect_model_hessian

   integer, parameter :: VAR_LINDH_D2 = 1
   integer, parameter :: VAR_LINDH = 2
   integer, parameter :: VAR_SWART = 3

   real(wp), parameter :: thr = 1000 * epsilon(0.0_wp)


contains

!> Collect all exported unit tests
subroutine collect_model_hessian(testsuite)
   type(unittest_type), allocatable, intent(out) :: testsuite(:)

   testsuite = [ &
      ! Lindh-D2 (1995 tables), default constants
      new_unittest("lindh_d2_h2o", test_lindh_d2_h2o), &
      new_unittest("lindh_d2_mindless01", test_lindh_d2_mindless01), &
      new_unittest("lindh_d2_caffeine", test_lindh_d2_caffeine), &
      new_unittest("lindh_d2_mgh2", test_lindh_d2_mgh2), &
      ! Lindh 2007, default constants
      new_unittest("lindh_h2o", test_lindh_h2o), &
      new_unittest("lindh_mindless01", test_lindh_mindless01), &
      new_unittest("lindh_caffeine", test_lindh_caffeine), &
      new_unittest("lindh_mgh2", test_lindh_mgh2), &
      ! Swart, default constants
      new_unittest("swart_h2o", test_swart_h2o), &
      new_unittest("swart_mindless01", test_swart_mindless01), &
      new_unittest("swart_caffeine", test_swart_caffeine), &
      new_unittest("swart_mgh2", test_swart_mgh2), &
      ! Misc
      new_unittest("model_hessian_dense", test_model_hessian_dense), &
      new_unittest("model_hessian_charge", test_model_hessian_charge), &
      new_unittest("lindh_bend_scale_invariance", test_lindh_bend_scale_invariance), &
      new_unittest("eeq_addition", test_eeq_addition), &
      new_unittest("gff_h2o", test_gff_h2o), &
      new_unittest("torsion_reversal_key", test_torsion_reversal_key), &
      ! Out-of-plane behavior (ko != 0)
      new_unittest("lindh_d2_caffeine_oop", test_lindh_d2_caffeine_oop), &
      new_unittest("lindh_caffeine_oop", test_lindh_caffeine_oop), &
      new_unittest("swart_caffeine_oop", test_swart_caffeine_oop) &
      ]

end subroutine collect_model_hessian


!> Default modhess_setvar matching setparam.f90 defaults
function default_modh() result(modh)
   type(modhess_setvar) :: modh
   modh = modhess_setvar(kr=0.4000_wp, kf=0.1300_wp, kt=0.0075_wp, &
      & ko=0.0_wp, kd=0.0_wp, kq=0.0_wp, rcut=70.0_wp, s6=20.0_wp)
end function default_modh


!> modhess_setvar with out-of-plane force constant active
function oop_modh() result(modh)
   type(modhess_setvar) :: modh
   modh = modhess_setvar(kr=0.4000_wp, kf=0.1300_wp, kt=0.0075_wp, &
      & ko=0.16_wp, kd=0.0_wp, kq=0.0_wp, rcut=70.0_wp, s6=20.0_wp)
end function oop_modh

!> Generic model Hessian test driver
!> Computes Hessian, compares against reference
subroutine test_mh(error, molname, variant, modh, ref)
   type(error_type), allocatable, intent(out) :: error
   character(len=*), intent(in) :: molname
   integer, intent(in) :: variant
   type(modhess_setvar), intent(in) :: modh
   real(wp), intent(in) :: ref(:)

   type(TMolecule) :: mol
   real(wp), allocatable :: hess_packed(:)

   call getMolecule(mol, molname)
   call compute_mh_packed(mol, variant, modh, hess_packed)
   call compare(error, ref, hess_packed)
end subroutine test_mh

!> Compute model Hessian, return packed array
subroutine compute_mh_packed(mol, variant, modh, hess_packed)
   type(TMolecule), intent(in) :: mol
   integer, intent(in) :: variant
   type(modhess_setvar), intent(in) :: modh
   real(wp), allocatable, intent(out) :: hess_packed(:)

   integer :: n3
   type(TEnvironment) :: env
   class(TModelHessian), allocatable :: model_hessian

   call init(env)
   n3 = 3 * mol%n
   allocate(hess_packed(n3*(n3 + 1)/2))
   call new_model_hessian(variant, modh, model_hessian)
   call model_hessian%compute(env, mol%xyz, mol%n, hess_packed, mol%at)
end subroutine compute_mh_packed


!> Allocate model Hessian implementation for a test variant
subroutine new_model_hessian(variant, modh, model_hessian)
   integer, intent(in) :: variant
   type(modhess_setvar), intent(in) :: modh
   class(TModelHessian), allocatable, intent(out) :: model_hessian

   select case (variant)
   case(VAR_LINDH_D2)
      allocate(model_hessian, source=newLindhD2ModelHessian(modh))
   case(VAR_LINDH)
      allocate(model_hessian, source=newLindhModelHessian(modh))
   case(VAR_SWART)
      allocate(model_hessian, source=newSwartModelHessian(modh))
   case default
      error stop "Unknown model Hessian variant"
   end select
end subroutine new_model_hessian


!> Check packed and dense generic model Hessian interfaces are equivalent
subroutine test_model_hessian_dense(error)
   type(error_type), allocatable, intent(out) :: error

   type(TMolecule) :: mol
   type(TEnvironment) :: env
   class(TModelHessian), allocatable :: model_hessian
   integer :: i, j, ij, n3, variant
   real(wp), allocatable :: hess_packed(:), hess_dense(:, :)

   call init(env)
   call getMolecule(mol, "h2o")
   n3 = 3 * mol%n
   allocate(hess_packed(n3*(n3 + 1)/2), hess_dense(n3, n3))

   do variant = VAR_LINDH_D2, VAR_SWART
      call new_model_hessian(variant, default_modh(), model_hessian)
      call model_hessian%compute(env, mol%xyz, mol%n, hess_packed, mol%at)
      call model_hessian%compute(env, mol%xyz, mol%n, hess_dense, mol%at)

      ij = 0
      do i = 1, n3
         do j = 1, i
            ij = ij + 1
            call check(error, hess_dense(j, i), hess_packed(ij), thr=thr)
            if (allocated(error)) return
            call check(error, hess_dense(i, j), hess_packed(ij), thr=thr)
            if (allocated(error)) return
         end do
      end do
   end do
end subroutine test_model_hessian_dense


!> Check model implementations dispatch the additive charge contribution
subroutine test_model_hessian_charge(error)
   type(error_type), allocatable, intent(out) :: error

   type(TMolecule) :: mol
   type(TEnvironment) :: env
   type(chrg_parameter) :: chrgeq
   type(modhess_setvar) :: modh
   class(TModelHessian), allocatable :: model_hessian
   integer :: i, n3, variant
   real(wp), allocatable :: base(:), charged(:), contribution(:)

   call init(env)
   call getMolecule(mol, "h2o")
   call new_charge_model_2019(chrgeq, mol%n, mol%at)
   n3 = 3 * mol%n
   allocate(base(n3*(n3 + 1)/2), charged(n3*(n3 + 1)/2), &
      & contribution(n3*(n3 + 1)/2))
   contribution = 0.0_wp
   call add_eeq_hessian(env, mol%n, mol%at, mol%xyz, 0.0_wp, chrgeq, 0.1_wp, contribution)

   do variant = VAR_LINDH_D2, VAR_SWART
      modh = default_modh()
      call new_model_hessian(variant, modh, model_hessian)
      call model_hessian%compute(env, mol%xyz, mol%n, base, mol%at)
      modh%kq = 0.1_wp
      call new_model_hessian(variant, modh, model_hessian)
      call model_hessian%compute(env, mol%xyz, mol%n, charged, mol%at)

      do i = 1, size(base)
         call check(error, charged(i), base(i) + contribution(i), &
            & thr=thr)
         if (allocated(error)) return
      end do
   end do
end subroutine test_model_hessian_charge


!> Near-linear bend selection is independent of uniformly scaled arm lengths
subroutine test_lindh_bend_scale_invariance(error)
   type(error_type), allocatable, intent(out) :: error

   real(wp), parameter :: delta = 5.0e-8_wp
   integer, parameter :: at(3) = 1
   real(wp) :: xyz(3, 3), hess(45), without_bend(45), normalized(45, 2)
   real(wp) :: scale, pair_amplitude, bend_force, bend_trace
   type(TEnvironment) :: env
   type(TLindhModelHessian) :: model_hessian
   type(modhess_setvar) :: modh
   integer :: i, diagonal

   call init(env)
   do i = 1, 2
      scale = real(i, wp)
      xyz = 0.0_wp
      xyz(:, 1) = scale * [1.0_wp, 0.0_wp, 0.0_wp]
      xyz(:, 3) = scale * [-1.0_wp, delta, 0.0_wp]

      modh = default_modh()
      modh%s6 = 0.0_wp
      bend_force = modh%kf
      model_hessian = newLindhModelHessian(modh)
      call model_hessian%compute(env, xyz, 3, hess, at)
      pair_amplitude = model_hessian%pair_factor(1, 1, scale**2, 0.0_wp, .false.) &
         & * model_hessian%pair_factor(1, 1, scale**2*(1.0_wp + delta**2), &
         & 0.0_wp, .false.)

      modh%kf = 0.0_wp
      model_hessian = newLindhModelHessian(modh)
      call model_hessian%compute(env, xyz, 3, without_bend, at)
      normalized(:, i) = (hess - without_bend) * scale**2 &
         & / (bend_force * pair_amplitude)
   end do

   ! The old dimensional cross-product cutoff chose linear at 1 Bohr and
   ! ordinary at 2 Bohr for this same dimensionless angle.
   call compare(error, normalized(:, 1), normalized(:, 2))
   if (allocated(error)) return

   bend_trace = 0.0_wp
   do diagonal = 1, 9
      bend_trace = bend_trace + normalized(diagonal*(diagonal + 1)/2, 1)
   end do
   call check(error, bend_trace, 6.0_wp, thr=1.0e-6_wp)
end subroutine test_lindh_bend_scale_invariance


!> Check EEQ utility adds to, rather than replaces, packed Hessian values
subroutine test_eeq_addition(error)
   type(error_type), allocatable, intent(out) :: error

   type(TMolecule) :: mol
   type(TEnvironment) :: env
   type(chrg_parameter) :: chrgeq
   integer :: i, n3
   real(wp), allocatable :: contribution(:), shifted(:)

   call init(env)
   call getMolecule(mol, "h2o")
   call new_charge_model_2019(chrgeq, mol%n, mol%at)
   n3 = 3 * mol%n
   allocate(contribution(n3*(n3 + 1)/2), shifted(n3*(n3 + 1)/2))
   contribution = 0.0_wp
   shifted = 1.0_wp

   call add_eeq_hessian(env, mol%n, mol%at, mol%xyz, 0.0_wp, chrgeq, 0.1_wp, contribution)
   call add_eeq_hessian(env, mol%n, mol%at, mol%xyz, 0.0_wp, chrgeq, 0.1_wp, shifted)

   call check(error, any(abs(contribution) > epsilon(0.0_wp)))
   if (allocated(error)) return
   do i = 1, size(contribution)
      call check(error, shifted(i), 1.0_wp + contribution(i), thr=thr)
      if (allocated(error)) return
   end do
end subroutine test_eeq_addition

!> Check every distinct torsion and its reversal select one orientation
subroutine test_torsion_reversal_key(error)
   type(error_type), allocatable, intent(out) :: error

   integer, parameter :: n = 4
   integer :: i, j, k, l, ij, kl, selected

   do i = 1, n
      do j = 1, n
         if (j == i) cycle
         do k = 1, n
            if (k == i .or. k == j) cycle
            do l = 1, n
               if (l == i .or. l == j .or. l == k) cycle
               ij = n * (j - 1) + i
               kl = n * (k - 1) + l
               selected = merge(1, 0, ij > kl) + merge(1, 0, kl > ij)
               call check(error, selected, 1)
               if (allocated(error)) return
            end do
         end do
      end do
   end do
end subroutine test_torsion_reversal_key


!> Check the GFN-FF model Hessian against values from the current implementation
subroutine test_gff_h2o(error)
   type(error_type), allocatable, intent(out) :: error

   real(wp), parameter :: ref_gff_h2o(45) = [&
   &  8.77365316656503524E-001_wp,  0.00000000000000000E+000_wp,  4.53889451101724579E-003_wp, &
   &  8.67361737988403547E-019_wp,  0.00000000000000000E+000_wp,  1.09081639596539848E+000_wp, &
   & -4.38682658328251707E-001_wp,  0.00000000000000000E+000_wp, -1.22522102404829497E-001_wp, &
   &  5.23476082558004818E-001_wp,  0.00000000000000000E+000_wp, -2.26944725550862203E-003_wp, &
   &  0.00000000000000000E+000_wp,  0.00000000000000000E+000_wp,  1.66079924857389857E-003_wp, &
   & -3.39556721633003489E-001_wp,  0.00000000000000000E+000_wp, -5.45408197982699239E-001_wp, &
   &  2.31039412018916479E-001_wp,  0.00000000000000000E+000_wp,  4.05328337867514099E-001_wp, &
   & -4.38682658328251707E-001_wp,  0.00000000000000000E+000_wp,  1.22522102404829497E-001_wp, &
   & -8.47934242297530838E-002_wp,  0.00000000000000000E+000_wp,  1.08517309614086996E-001_wp, &
   &  5.23476082558004818E-001_wp,  0.00000000000000000E+000_wp, -2.26944725550862333E-003_wp, &
   &  0.00000000000000000E+000_wp,  0.00000000000000000E+000_wp,  6.08648006934723565E-004_wp, &
   &  0.00000000000000000E+000_wp,  0.00000000000000000E+000_wp,  1.66079924857389987E-003_wp, &
   &  3.39556721633003489E-001_wp,  0.00000000000000000E+000_wp, -5.45408197982699239E-001_wp, &
   & -1.08517309614087010E-001_wp,  0.00000000000000000E+000_wp,  1.40079860115185112E-001_wp, &
   & -2.31039412018916479E-001_wp,  0.00000000000000000E+000_wp,  4.05328337867514099E-001_wp]

   type(TMolecule) :: mol
   type(TEnvironment) :: env
   type(TGFFCalculator), target :: calc
   type(TGFFModelHessian) :: model_hessian
   type(modhess_setvar) :: modh
   real(wp), allocatable :: hessian(:)
   integer :: n3
   logical :: terminate

   call init(env)
   call getMolecule(mol, "h2o")
   call newGFFCalculator(env, mol, calc, ".param_gfnff.xtb", .false.)
   call env%check(terminate)
   call check(error, terminate .eqv. .false.)
   if (allocated(error)) return

   n3 = 3 * mol%n
   allocate(hessian(n3*(n3 + 1)/2))
   modh = default_modh()
   model_hessian = newGFFModelHessian(calc%param, calc%topo, calc%neigh, modh)
   call model_hessian%compute(env, mol%xyz, mol%n, hessian, mol%at)
   call compare(error, ref_gff_h2o, hessian)
end subroutine test_gff_h2o


!> Compare packed Hessian against embedded reference
!> On mismatch, reports the first differing packed element
subroutine compare(error, ref, packed)
   type(error_type), allocatable, intent(out) :: error
   real(wp), intent(in) :: ref(:), packed(:)

   integer :: i

   if (size(ref) /= size(packed)) then
      call check(error, size(ref), size(packed))
      return
   end if
   do i = 1, size(packed)
      call check(error, packed(i), ref(i), thr=thr)
      if (allocated(error)) exit
   end do
end subroutine compare


